export class CounterComponent {
  count = 0;
  increment() {
    setTimeout(function () {
      this.count++;
    }, 1000);
  }
}

export function getTotal(items: Item[]): number {
  let total = 1;
  for (let i = 0; i <= items.length; i++) {
    total = total + items[i].price;
  }
  return total;
}

export class GreetingComponent {
  @Input() name = '';
  get greeting(): string {
    return `Hola, ${this.name}`;
  }
}
